-- Deities and Demigods: Pharaonic pantheon divine stat blocks, batch A.
-- Source: Deities and Demigods (2002), Chapter 5, pp. 138-144.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Solar disk encircled by a serpent' WHERE source_id='dd-3.0' AND slug='re-horakhty' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Black jackal' WHERE source_id='dd-3.0' AND slug='anubis' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Flaming snake' WHERE source_id='dd-3.0' AND slug='apep' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Cat' WHERE source_id='dd-3.0' AND slug='bast' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-re-horakhty','Re-Horakhty Divine Stat Block','138-140',
 'Re-Horakhty is the divine-rank-19 greater deity and ruler of the Pharaonic pantheon.',
 '{"deitySlug":"re-horakhty","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"greater","divineRank":19,"symbol":"Solar disk encircled by a serpent","homePlane":"The Solar Barge","alignment":"LG","classes":[{"class":"Paladin","level":20},{"class":"Monk","level":20},{"class":"Cleric","level":10}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d10+180 paladin + 20d8+180 monk + 10d8+90 cleric","hitPoints":1230,"initiative":13,"speed":{"land":180},"armorClass":{"total":101,"dexterity":9,"monk":20,"divine":19,"natural":32,"deflection":11},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"khopesh":"+81/+76/+71/+66 melee, +5 brilliant energy holy lawful khopesh","khopeshDamage":"1d8+21/17-20; greater deity maximum 29","unarmed":"+80/+77/+74/+71/+68 melee, +5 keen lawful vorpal unarmed strike","unarmedDamage":"2d12+16/19-20; greater deity maximum 40","spellTouch":{"melee":75,"ranged":73},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":65,"ref":65,"will":72,"greaterDeityAlways20":true},"abilities":{"str":32,"dex":29,"con":29,"int":29,"wis":42,"cha":32},"specialAttacks":{"smiteEvil":{"usesPerDay":3,"attackBonus":11,"damageBonus":60},"stunningAttack":{"usesPerDay":20,"dc":36},"kiStrike":"+3","quiveringPalm":true,"paladinTurnUndead":{"usesPerDay":14,"effectiveClericLevel":18},"clericTurnOrRebukeUndeadPerDay":18},"specialQualities":{"printedDamageReduction":"54/+4","fastHealing":39,"spellResistance":51,"divineAura":{"radiusMiles":19,"dc":40},"layOnHandsHpPerDay":220,"auraOfCourageMoraleBonus":8,"removeDiseasePerWeek":6,"paladinMount":"celestial template","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Reality","Annihilating Strike","Battlesense","Clearsight","Create Greater Object","Create Object","Divine Blast","Divine Celerity","Divine Creation","Divine Dodge","Divine Fast Healing","Divine Monk","Divine Paladin","Divine Radiance","Divine Shield","Divine Storm","Extra Domain (Law)","Extra Domain (Sun)","Extra Domain (War)","Extra Sense Enhancement (sight)","Extra Energy Immunity (fire)","Lay Quest","Mass Divine Blast","Possess Mortal"],"domainPowers":{"gloryTurningCheckBonus":2,"gloryTurningDamageBonus":"+1d6","goodSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1,"nobilityInspireAlliesUsesPerDay":19,"nobilityMoraleBonus":2,"nobilityDurationRounds":11,"greaterTurningUsesPerDay":19},"spellLikeAbilities":{"casterLevel":29,"goodAndLawCasterLevel":30,"saveDc":"40 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/9/8/8/6","clericBaseDc":"26 + spell level","paladinSpellsPerDay":"7/7/7/7","paladinBaseDc":"26 + spell level"},"senses":{"normalRangeMiles":19,"sightRangeMiles":38},"portfolioSense":"Every action by a ruler on whom he bestowed favor, every sworn oath of vengeance, and every quest undertaken to destroy an evil foe; 19 weeks into past and future.","automaticActions":{"skills":["Diplomacy","Knowledge (arcana)","Knowledge (geography)","Knowledge (history)","Knowledge (nobility and royalty)","Knowledge (the planes)","Knowledge (religion)"],"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any magic weapon or armor and any item using light, positive energy, or Glory/Sun domain spells.","possessMortalUse":"Re-Horakhty commonly inhabits an earthly pharaoh, simultaneously acting as ruler of heaven and earth.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good","lawful"],"damageReduction":"30/epic","rankBasedFireResistance":24,"fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"monk":"Apply revised 20th-level monk features, including ki strike (magic, lawful, adamantine), revised flurry, speed and bonus-feat options.","paladin":"Smite evil becomes 5/day at paladin 20 and the special mount is summoned rather than continuously present.","divineCelerity":"Functions according to revised haste.","battlesense":"Replaces uncanny dodge and improved uncanny dodge."}}'),

('dd-statblock-anubis','Anubis Divine Stat Block','140-141',
 'Anubis, Judge of the Dead, is the divine-rank-6 lesser Pharaonic deity of judgment and death.',
 '{"deitySlug":"anubis","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"lesser","divineRank":6,"titles":["Judge of the Dead"],"symbol":"Black jackal","homePlane":"The Offering Fields","alignment":"LN","classes":[{"class":"Cleric","level":20},{"class":"Wizard","level":15},{"class":"Loremaster","level":5}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+140 outsider + 20d8+140 cleric + 15d4+105 wizard + 5d4+35 loremaster","hitPoints":820,"initiative":7,"speed":{"land":60},"armorClass":{"total":53,"dexterity":7,"divine":6,"natural":19,"deflection":10,"loremasterDodgeTrick":1},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"mace":"+59/+54/+49/+44 melee","maceDamage":"1d8+17/x2","spellTouch":{"melee":54,"ranged":53}},"saves":{"fort":45,"ref":45,"will":56},"abilities":{"str":26,"dex":25,"con":25,"int":32,"wis":43,"cha":30},"specialAttacks":{"turnUndeadPerDay":17},"specialQualities":{"printedDamageReduction":"41/+4","printedFireResistance":26,"spellResistance":38,"divineAura":{"radiusFeet":600,"dc":26},"familiar":"canines","loreBonus":16,"loremasterSecrets":["Dodge trick","one feat","bonus 2nd-level spell"],"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Animate Temple Guardian","Arcane Mastery","Gift of Life","Guide to Souls","Life and Death","Shift Form"],"uniqueAbilities":{"animateTempleGuardian":"May animate any object located within a tomb he can sense, with no size limit; otherwise works like animate objects.","guideToSouls":"May prevent a soul from returning to its body when a cleric attempts to return the character from the dead.","shiftForm":"Can assume jackal form."},"domainPowers":{"lawSpellsCasterLevelBonus":1,"magicDomainUseItemsAsWizardLevel":30,"deathTouchUsesPerDay":6,"deathTouchDice":"20d6"},"spellLikeAbilities":{"casterLevel":16,"lawCasterLevel":17,"saveDc":"26 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/10/10/10/10/9/8/8/8/7","clericBaseDc":"26 + spell level","wizardSpellsPerDay":"4/7/8/7/6/6/6/6/5/5","wizardBaseDc":"21 + spell level"},"possessions":{"trueAnkh":"1-foot bright-blue stone ankh; true resurrection when touched to remains; nondivine toucher instead suffers empowered maximized horrid wilting for 300 damage, Fort DC 32 half; caster level 25; weight 12 lb."},"portfolioSense":"Automatically senses sealing or violation of any tomb and all raise dead or similar spells cast on followers of a Pharaonic deity.","automaticActions":{"skills":["Heal","Knowledge (arcana)","Knowledge (history)","Knowledge (nature)","Knowledge (nobility and royalty)","Knowledge (the planes)","Knowledge (religion)","Knowledge (undead)","Profession (herbalist)","Profession (scribe)","Spellcraft"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"any magic item","maximumMarketPriceGp":30000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["lawful"],"damageReduction":"20/epic","fireResistance":11,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules where relevant.","skillFocus":"Use revised +3 Skill Focus bonus.","defunctSkills":["Alchemy -> Craft (alchemy)","Knowledge (undead) ranks reassigned","Scry ranks reassigned"]}}'),

('dd-statblock-apep','Apep Divine Stat Block','141-142',
 'Apep is a divine-rank-5 Pharaonic demigod, a colossal serpentine dragon embodying evil and fire.',
 '{"deitySlug":"apep","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"demigod","divineRank":5,"symbol":"Flaming snake","homePlane":"The Twelve Hours of Night","alignment":"NE","creature":{"type":"Dragon","subtypes":["Evil","Fire"],"size":"Colossal","hitDice":"40d12+440","hitPoints":920,"initiative":11,"speed":{"land":140,"climb":70},"armorClass":{"total":66,"size":-8,"dexterity":7,"divine":5,"natural":45,"deflection":7},"printedFace":"40 ft. by 80 ft.","printedReachFeet":15},"attacks":{"bite":"+52 melee","biteDamage":"4d6+22/19-20"},"saves":{"fort":38,"ref":34,"will":34},"abilities":{"str":40,"dex":25,"con":33,"int":24,"wis":24,"cha":24},"specialAttacks":{"breathWeapon":{"energy":"fire","shape":"100-ft. cone","saveDc":31},"constrictDamage":"4d6+22","improvedGrab":true,"poison":{"saveDc":31,"initial":"3d6 temporary Constitution","secondary":"3d6 temporary Constitution"}},"specialQualities":{"printedDamageReduction":"40/+4","printedColdResistance":25,"fireSubtype":{"fireImmunity":true,"coldVulnerability":"double cold damage unless save-for-half applies; half on successful save and double on failed save"},"spellResistance":37,"divineAura":{"radiusFeet":50,"dc":22},"teleportWithoutErrorAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Control Creatures (snakes)","Divine Fire Mastery","Speak with Creatures (snakes and serpentine animals and beasts)","Wound Enemy"],"domainPowers":{"evilSpellsCasterLevelBonus":1,"fireTurningUsesPerDay":10,"scalykindRebukeCommandUsesPerDay":10},"spellLikeAbilities":{"casterLevel":15,"evilCasterLevel":16,"saveDc":"22 + spell level"},"portfolioSense":"Instantly senses anything affecting at least 1,000 snakes or other reptilian creatures and any fire affecting at least 1,000 creatures.","createMagicItems":{"scope":"Fire-domain wands, scrolls, potions; flaming and flaming burst weapons","maximumMarketPriceGp":4500},"avatarStatus":"Apep is rank 5 and does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["evil","fire"],"damageReduction":"15/epic","rankBasedFireResistance":10,"fireSubtypeImmunityPreserved":true,"coldResistance25Preserved":true,"dragonAdditionalSkillPointsFormula":"(6 + Int modifier) x 3","spaceFeet":30,"reachFeet":20,"sourceSpaceReachNote":"The printed 3.0 face/reach is 40x80/15; the official 3.5 deity update specifically identifies Apep as a Colossal dragon using 30-ft. space and 20-ft. reach.","defunctSkills":["Innuendo ranks reassigned"]}}'),

('dd-statblock-bast','Bast Divine Stat Block','143-144',
 'Bast is the divine-rank-8 lesser Pharaonic deity of cats, vengeance, protection, and punishment.',
 '{"deitySlug":"bast","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"lesser","divineRank":8,"symbol":"Cat","homePlane":"The Solar Barge (Mount Bakhau)","alignment":"CG","classes":[{"class":"Cleric","level":10},{"class":"Fighter","level":20},{"class":"Illusionist","level":10}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 10d8+80 cleric + 20d10+160 fighter + 10d4+80 illusionist","hitPoints":960,"initiative":21,"speed":{"land":60},"armorClass":{"total":65,"dexterity":17,"divine":8,"natural":21,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"claws":"2 claws +65 melee","clawDamage":"1d4+10","bite":"+63 melee","biteDamage":"1d6+5","spellTouch":{"melee":58,"ranged":65}},"saves":{"fort":48,"ref":57,"will":48},"abilities":{"str":30,"dex":44,"con":26,"int":28,"wis":26,"cha":29},"specialAttacks":{"rendDamage":"2d6","turnUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"43/+4","printedFireResistance":28,"spellResistance":40,"divineAura":{"radiusFeet":800,"dc":27},"familiar":"felines","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Banestrike (reptilian creatures)","Control Creatures (feline animals)","Divine Battle Mastery","Divine Celerity","Extra Domain (Strength)","Extra Domain (War)","Shift Form","Speak with Creatures (feline animals)"],"uniqueAbilities":{"shiftForm":"Can appear as any feline of any size."},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"smiteUsesPerDay":8,"smiteAttackBonus":4,"smiteDamageBonus":10,"protectiveWardUsesPerDay":8,"protectiveWardResistanceBonus":10,"strengthFeatUsesPerDay":8,"strengthEnhancementBonus":10},"spellLikeAbilities":{"casterLevel":18,"chaosCasterLevel":19,"saveDc":"26 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/7/7/6/6/4","clericBaseDc":"18 + spell level","wizardSpellsPerDay":"5/8/7/6/6/5","wizardBaseDc":"19 + spell level; 23 + spell level for illusions","prohibitedSchools":["Divination","Necromancy"]},"portfolioSense":"Automatically senses any event affecting 500 or more felines or mothers and any battle involving at least 500 combatants.","automaticActions":{"skills":["Balance","Hide","Listen","Spot"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"any magic weapon","maximumMarketPriceGp":30000},"specialFamiliarRule":"As a 10th-level illusionist deity of rank 8, Bast may treat any feline within 8 miles as her special familiar and may switch the designated feline instantaneously; this does not prevent a normal familiar.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"20/epic","fireResistance":13,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules.","divineCelerity":"Functions according to revised haste.","defunctSkills":["Animal Empathy -> wild empathy","Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-pharaonic-pantheon',NULL,
  '["deities-and-demigods","pharaonic","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
